\begin{lstlisting}[
    language=DDYaml,
    caption={Declarative YAML dataset configuration.},
    label={lst:declarative-yaml}
]
columns:
  - name: audience
    column_type: sampler
    sampler_type: category
    params:
      values: [developer, analyst, student]

  - name: goal
    column_type: sampler
    sampler_type: category
    params:
      values: [definition, comparison]

  - name: answer
    column_type: llm-text
    model_alias: nvidia-text
    prompt: >
      Write a {{ goal }} answer for a
      {{ audience }} about dependency-aware
      synthetic data generation.

processors:
  - name: chat_view
    processor_type: schema_transform
    template:
      messages:
        - role: user
          content: "Explain {{ goal }}."
        - role: assistant
          content: "{{ answer }}"
\end{lstlisting}

