\begin{lstlisting}[
    language=Python,
    caption={Equivalent Python builder configuration.},
    label={lst:declarative-python}
]
import data_designer.config as dd

builder = dd.DataDesignerConfigBuilder()
builder.add_column(dd.SamplerColumnConfig(
    name="audience",
    sampler_type=dd.SamplerType.CATEGORY,
    params=dd.CategorySamplerParams(
        values=["developer", "analyst", "student"],
    ),
))
builder.add_column(dd.SamplerColumnConfig(
    name="goal",
    sampler_type=dd.SamplerType.CATEGORY,
    params=dd.CategorySamplerParams(
        values=["definition", "comparison"],
    ),
))
builder.add_column(dd.LLMTextColumnConfig(
    name="answer",
    model_alias="nvidia-text",
    prompt=(
        "Write a {{ goal }} answer for a "
        "{{ audience }} about dependency-aware "
        "synthetic data generation."
    ),
))
builder.add_processor(dd.SchemaTransformProcessorConfig(
    name="chat_view",
    template={"messages": [
        {"role": "user", "content": "Explain {{ goal }}."},
        {"role": "assistant", "content": "{{ answer }}"},
    ]},
))
\end{lstlisting}


